package main

import (
	"bufio"
	"fmt"
	"os"
)

const (
	UP    = 0
	DOWN  = 1
	LEFT  = 2
	RIGHT = 3
)

const (
	UPLEFT    = 4
	UPRIGHT   = 5
	DOWNLEFT  = 6
	DOWNRIGHT = 7
)

var dx = []int{0, 0, -1, 1, -1, 1, -1, 1}
var dy = []int{1, -1, 0, 0, 1, 1, -1, -1}

const MAX = 5*30 + 5

var marked []bool

func idx(a, b, c, d, e int) int {
	return ((((a*(2*MAX)+b)*8+c)*32+d)*6 + e)
}

var mp = make(map[[2]int]bool)
var t [100]int

func rot(dir int) (int, int) {
	switch dir {
	case UP:
		return UPLEFT, UPRIGHT
	case DOWN:
		return DOWNLEFT, DOWNRIGHT
	case LEFT:
		return UPLEFT, DOWNLEFT
	case RIGHT:
		return UPRIGHT, DOWNRIGHT
	case UPLEFT:
		return UP, LEFT
	case UPRIGHT:
		return UP, RIGHT
	case DOWNLEFT:
		return DOWN, LEFT
	case DOWNRIGHT:
		return DOWN, RIGHT
	}
	return 0, 0
}

type node struct {
	x, y, dir int
	lev, far  int
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	marked = make([]bool, (2*MAX)*(2*MAX)*8*32*6)

	var n int
	fmt.Fscan(reader, &n)
	for i := 1; i <= n; i++ {
		fmt.Fscan(reader, &t[i])
	}

	ans := 0
	Q := make([]node, 0)
	Q = append(Q, node{MAX, MAX, UP, 1, 1})

	marked[idx(MAX, MAX, UP, 1, 1)] = true
	mp[[2]int{MAX, MAX}] = true
	ans++

	for len(Q) > 0 {
		v := Q[0]
		Q = Q[1:]

		if !mp[[2]int{v.x, v.y}] {
			mp[[2]int{v.x, v.y}] = true
			ans++
		}

		lev := v.lev
		far := v.far

		x2, y2 := v.x, v.y

		if lev == n+1 {
			continue
		}

		if far != t[lev] {
			x2 += dx[v.dir]
			y2 += dy[v.dir]
			if marked[idx(x2, y2, v.dir, lev, far+1)] {
				continue
			}
			marked[idx(x2, y2, v.dir, lev, far+1)] = true
			Q = append(Q, node{x2, y2, v.dir, lev, far + 1})
		} else {
			d1, d2 := rot(v.dir)
			if !marked[idx(v.x, v.y, d1, lev+1, 0)] {
				marked[idx(v.x, v.y, d1, lev+1, 0)] = true
				Q = append(Q, node{v.x, v.y, d1, lev + 1, 0})
			}
			if !marked[idx(v.x, v.y, d2, lev+1, 0)] {
				marked[idx(v.x, v.y, d2, lev+1, 0)] = true
				Q = append(Q, node{v.x, v.y, d2, lev + 1, 0})
			}
		}
	}
	fmt.Fprintln(writer, ans)
}
